#include <bits/stdc++.h>
using namespace std;

const long long M = 1000000007LL;

long long getx(unsigned long long n) {
    if (n < 30) {
        return 1LL << n;
    }
    if (n % 2 == 0) {
        long long y = getx(n >> 1);
        return (y * y) % M;
    }
    return (getx(n - 1) * 2) % M;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    unsigned long long N, K;
    if (!(cin >> N >> K)) return 0;

    if (N == 0) {
        cout << 0 << '\n';
        return 0;
    }

    N %= M;
    N = (2 * N - 1 + M) % M;

    long long z = getx(K);
    cout << (z * N + 1) % M << '\n';

    return 0;
}

